CREATE OR REPLACE TABLE "retail_lines" AS
WITH sheets AS (SELECT 'Year 2009-2010' AS sheet, * FROM read_xlsx('data/online_retail_II.xlsx', sheet = 'Year 2009-2010', all_varchar = true) UNION ALL SELECT 'Year 2010-2011' AS sheet, * FROM read_xlsx('data/online_retail_II.xlsx', sheet = 'Year 2010-2011', all_varchar = true)), typed AS (SELECT sheet, Invoice AS invoice, StockCode AS stock_code, Description AS description, CAST(Quantity AS INTEGER) AS quantity, TIMESTAMP '1899-12-30' + to_microseconds(CAST(round(CAST(InvoiceDate AS DOUBLE) * 86400) AS BIGINT) * 1000000) AS invoice_time, CAST(Price AS DOUBLE) AS price, "Customer ID" AS customer, Country AS country FROM sheets), once AS (SELECT * FROM typed WHERE sheet = 'Year 2010-2011' OR invoice_time < (SELECT min(invoice_time) FROM typed WHERE sheet = 'Year 2010-2011')) SELECT invoice, stock_code, description, quantity, invoice_time, price, country, customer IS NOT NULL AS customer_id_recorded, CASE WHEN customer IS NOT NULL THEN CAST(min(CASE WHEN invoice NOT LIKE 'C%' THEN date_trunc('month', invoice_time) END) OVER (PARTITION BY customer) AS DATE) END AS customer_first_month, CASE WHEN customer IS NOT NULL AND invoice NOT LIKE 'C%' THEN dense_rank() OVER (PARTITION BY customer, invoice LIKE 'C%' ORDER BY invoice_time, invoice) END AS customer_order_number FROM once
